-- Compagnies aériennes : libellés et logos des codes IATA rendus par Duffel (programmes de fidélité, transporteurs…).
-- Généré depuis l'API Duffel GET /air/airlines (787 compagnies ayant un code IATA, sur 857).

CREATE TABLE airline
(
    iata                       CHAR(2) PRIMARY KEY,
    name                       TEXT NOT NULL,
    logo_symbol_url            TEXT,
    logo_lockup_url            TEXT,
    conditions_of_carriage_url TEXT
);

